								"type": "string",
								"enum": [
									"client_secret_basic",
									"client_secret_post",
									"client_secret_jwt",
									"private_key_jwt",
									"none"
								],
								"default": "client_secret_post",
								"title": "ClientAuthentication",
								"description": "The authentication method to use to authenticate the client."
